package com.gathin.tvhome;
import android.content.Context;import android.util.AtomicFile;import java.io.*;import java.util.*;import org.json.*;
/** CSS-only user themes. Templates and JavaScript remain owned by the bundled base theme. */
final class AuroraCssThemes{
 static final String[] BASES={"foundation","immersive","elder","cards","waterfall","legacy"};
 static File catalog(Context c)throws Exception{return new File(AuroraThemes.root(c),"custom/themes.json");}
 static JSONArray entries(Context c)throws Exception{File f=catalog(c);if(!f.isFile())return new JSONArray();try(InputStream in=new FileInputStream(f)){return new JSONArray(new String(AuroraThemes.read(in,262144),"UTF-8"));}}
 static void writeFile(File f,String text)throws Exception{File parent=f.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("无法创建主题目录");AtomicFile a=new AtomicFile(f);FileOutputStream out=a.startWrite();try{out.write(text.getBytes("UTF-8"));a.finishWrite(out);}catch(Exception e){a.failWrite(out);throw e;}}
 static JSONObject find(Context c,String id)throws Exception{AuroraThemes.id(id);JSONArray all=entries(c);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("id").equals(id))return all.getJSONObject(i);throw new IllegalArgumentException("自定义主题不存在");}
 static String known(Context c,String id)throws Exception{AuroraThemes.id(id);if(!Arrays.asList(BASES).contains(id))find(c,id);return id;}
 static File cssFile(Context c,String id)throws Exception{return new File(AuroraThemes.root(c),"custom/css/"+known(c,id)+".css");}
 static synchronized String css(Context c,String id)throws Exception{File f=cssFile(c,id);if(!f.isFile()&&id.equals("foundation"))f=new File(AuroraThemes.root(c),"custom/theme.css");if(!f.isFile())return "";try(InputStream in=new FileInputStream(f)){return new String(AuroraThemes.read(in,65536),"UTF-8");}}
 static synchronized JSONObject saveCss(Context c,String id,String value)throws Exception{known(c,id);AuroraSettings.validateCss(value);writeFile(cssFile(c,id),value);JSONObject config=AuroraThemes.config(c);config.put("customCssUpdatedAt",System.currentTimeMillis());AuroraThemes.save(c,config);return new JSONObject().put("theme",id).put("css",value).put("applicable",!id.equals("legacy"));}
 static JSONObject manifest(Context c,String id)throws Exception{JSONObject entry=find(c,id),base=AuroraThemes.manifest(c,entry.getString("base"));return new JSONObject(base.toString()).put("id",id).put("name",entry.getString("name")).put("base",entry.getString("base")).put("custom",true).put("readOnly",false);}
 static synchronized JSONObject create(Context c,JSONObject body)throws Exception{AuroraSettings.only(body,"name","base","css");String name=body.getString("name").trim(),base=body.getString("base");if(name.isEmpty()||name.length()>40||name.matches(".*[\\p{Cntrl}].*"))throw new IllegalArgumentException("名称请输入1～40个字符");if(!Arrays.asList(BASES).contains(base)||base.equals("legacy"))throw new IllegalArgumentException("请选择已完成的网页主题作为基础");AuroraThemes.manifest(c,base);JSONArray all=entries(c);if(all.length()>=50)throw new IllegalArgumentException("最多保存50个自定义主题");String value=body.optString("css","");AuroraSettings.validateCss(value);String id="user_"+UUID.randomUUID().toString().replace("-","");JSONObject entry=new JSONObject().put("id",id).put("name",name).put("base",base);writeFile(new File(AuroraThemes.root(c),"custom/css/"+id+".css"),value);all.put(entry);writeFile(catalog(c),all.toString());return manifest(c,id);}
 static synchronized void remove(Context c,JSONObject body)throws Exception{AuroraSettings.only(body,"id","confirm");String id=body.getString("id");find(c,id);if(!body.optBoolean("confirm"))throw new IllegalArgumentException("请确认删除");if(AuroraThemes.current(c).equals(id))throw new IllegalArgumentException("请先切换到其他主题");JSONArray next=new JSONArray(),all=entries(c);for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("id").equals(id))next.put(all.get(i));writeFile(catalog(c),next.toString());cssFileUnchecked(c,id).delete();}
 static File cssFileUnchecked(Context c,String id)throws Exception{return new File(AuroraThemes.root(c),"custom/css/"+AuroraThemes.id(id)+".css");}
 static byte[] asset(Context c,String path)throws Exception{String[] parts=path.split("/",3);if(parts.length!=3)throw new IllegalArgumentException("主题资源路径不完整");JSONObject m=find(c,parts[1]);String base=m.getString("base");if(parts[2].equals("theme.json"))return manifest(c,parts[1]).toString().getBytes("UTF-8");byte[] bytes=AuroraThemes.asset(c,"themes/"+base+"/"+parts[2]);if(parts[2].endsWith(".html"))return new String(bytes,"UTF-8").replace("/themes/"+base+"/","/themes/"+parts[1]+"/").getBytes("UTF-8");return bytes;}
}